//! Custom backgrounds are normalized into an immutable application-owned cache.
use galgear_i18n::Message;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::{fs, io::Read, io::Write, path::Path, path::PathBuf};

const MAX_FILE_BYTES: u64 = 32 * 1024 * 1024;
const MAX_IMAGE_SIDE: u32 = 20_000;
const MAX_DISPLAY_SIDE: u32 = 2560;

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct BackgroundImage {
    pub id: String,
    pub name: String,
}

/// Only content identifiers generated by the importer can address cached images.
pub fn cache_path(cache: &Path, id: &str) -> Option<PathBuf> {
    (id.len() == 64
        && id
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)))
    .then(|| cache.join(format!("{id}.jpg")))
}

fn image_error(error: image::ImageError) -> Message {
    Message::new(if matches!(error, image::ImageError::Limits(_)) {
        "background.too_large"
    } else {
        "background.invalid"
    })
}

/// Validate and copy a selected image so moving the original cannot break the background.
pub fn import(source: &Path, cache: &Path) -> Result<BackgroundImage, Message> {
    let file = fs::File::open(source).map_err(|_| Message::new("background.invalid"))?;
    if file
        .metadata()
        .map_err(|_| Message::new("background.invalid"))?
        .len()
        > MAX_FILE_BYTES
    {
        return Err(Message::new("background.too_large"));
    }
    let mut bytes = Vec::new();
    file.take(MAX_FILE_BYTES + 1)
        .read_to_end(&mut bytes)
        .map_err(|_| Message::new("background.invalid"))?;
    if bytes.len() as u64 > MAX_FILE_BYTES {
        return Err(Message::new("background.too_large"));
    }
    let mut reader = image::ImageReader::new(std::io::Cursor::new(bytes))
        .with_guessed_format()
        .map_err(|_| Message::new("background.invalid"))?;
    if !matches!(
        reader.format(),
        Some(
            image::ImageFormat::Png
                | image::ImageFormat::Jpeg
                | image::ImageFormat::WebP
                | image::ImageFormat::Bmp
        )
    ) {
        return Err(Message::new("background.invalid"));
    }
    let mut limits = image::Limits::default();
    limits.max_image_width = Some(MAX_IMAGE_SIDE);
    limits.max_image_height = Some(MAX_IMAGE_SIDE);
    limits.max_alloc = Some(128 * 1024 * 1024);
    reader.limits(limits);
    let image = reader
        .decode()
        .map_err(image_error)?
        .thumbnail(MAX_DISPLAY_SIDE, MAX_DISPLAY_SIDE)
        .to_rgba8();
    let image = image::RgbImage::from_fn(image.width(), image.height(), |x, y| {
        let pixel = image.get_pixel(x, y);
        let alpha = u16::from(pixel[3]);
        // JPEG has no alpha channel; composite transparent areas onto a neutral white canvas.
        image::Rgb(std::array::from_fn(|channel| {
            ((u16::from(pixel[channel]) * alpha + 255 * (255 - alpha) + 127) / 255) as u8
        }))
    });
    let mut output = std::io::Cursor::new(Vec::new());
    image::DynamicImage::ImageRgb8(image)
        .write_to(&mut output, image::ImageFormat::Jpeg)
        .map_err(image_error)?;
    let bytes = output.into_inner();
    let id = format!("{:x}", Sha256::digest(&bytes));
    let destination = cache_path(cache, &id).ok_or_else(|| Message::new("background.invalid"))?;
    fs::create_dir_all(cache).map_err(|error| Message::detail("error.operation", error))?;
    if !destination.exists() {
        let mut file = tempfile::NamedTempFile::new_in(cache)
            .map_err(|error| Message::detail("error.operation", error))?;
        file.write_all(&bytes)
            .map_err(|error| Message::detail("error.operation", error))?;
        file.as_file()
            .sync_all()
            .map_err(|error| Message::detail("error.operation", error))?;
        // The content hash makes a concurrent atomic replacement byte-identical.
        file.persist(destination)
            .map_err(|error| Message::detail("error.operation", error.error))?;
    }
    Ok(BackgroundImage {
        id,
        name: source
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_default(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn selected_image_is_resized_and_survives_the_original_being_removed() {
        let root = tempfile::tempdir().unwrap();
        let source = root.path().join("自选背景.png");
        let cache = root.path().join("cache");
        image::RgbImage::from_pixel(3000, 1500, image::Rgb([200, 160, 190]))
            .save(&source)
            .unwrap();
        let background = import(&source, &cache).unwrap();
        fs::remove_file(source).unwrap();
        let image = image::open(cache_path(&cache, &background.id).unwrap()).unwrap();
        assert_eq!(
            (background.name.as_str(), image.width(), image.height()),
            ("自选背景.png", 2560, 1280)
        );
    }

    #[test]
    fn corrupt_image_does_not_create_a_cache_entry() {
        let root = tempfile::tempdir().unwrap();
        let source = root.path().join("bad.png");
        let cache = root.path().join("cache");
        fs::write(&source, b"not an image").unwrap();
        assert_eq!(
            import(&source, &cache).unwrap_err().key,
            "background.invalid"
        );
        assert!(!cache.exists());
    }

    #[test]
    fn transparent_backgrounds_are_composited_onto_white_before_jpeg_encoding() {
        let root = tempfile::tempdir().unwrap();
        let source = root.path().join("transparent.png");
        image::RgbaImage::from_pixel(4, 4, image::Rgba([0, 0, 0, 0]))
            .save(&source)
            .unwrap();
        let background = import(&source, root.path()).unwrap();
        let image = image::open(cache_path(root.path(), &background.id).unwrap())
            .unwrap()
            .to_rgb8();
        assert!(
            image
                .get_pixel(0, 0)
                .0
                .iter()
                .all(|channel| *channel >= 250)
        );
    }

    #[test]
    fn oversize_input_is_rejected_before_decoding() {
        let root = tempfile::tempdir().unwrap();
        let source = root.path().join("large.png");
        fs::File::create(&source)
            .unwrap()
            .set_len(MAX_FILE_BYTES + 1)
            .unwrap();
        assert_eq!(
            import(&source, root.path()).unwrap_err().key,
            "background.too_large"
        );
    }

    #[test]
    fn oversized_dimensions_are_rejected_before_image_allocation() {
        let root = tempfile::tempdir().unwrap();
        let source = root.path().join("wide.bmp");
        image::RgbImage::new(MAX_IMAGE_SIDE + 1, 1)
            .save(&source)
            .unwrap();
        assert_eq!(
            import(&source, root.path()).unwrap_err().key,
            "background.too_large"
        );
    }

    #[test]
    fn image_identifiers_cannot_escape_the_cache() {
        let cache = Path::new("backgrounds");
        for id in [
            "../settings",
            "../../a.jpg",
            "",
            &"A".repeat(64),
            &"f".repeat(63),
        ] {
            assert!(cache_path(cache, id).is_none());
        }
        assert_eq!(
            cache_path(cache, &"a".repeat(64)),
            Some(cache.join(format!("{}.jpg", "a".repeat(64))))
        );
    }
}
